-static constexpr std::array ucode_handlers = {
-    &f3dHandlers,    // ucode_f3db
-    &f3dHandlers,    // ucode_f3d
-    &f3dexHandlers,  // ucode_f3dex
-    &f3dexHandlers,  // ucode_f3dexb
-    &f3dex2Handlers, // ucode_f3dex2
-    &s2dexHandlers,  // ucode_s2dex
-};
