+std::shared_ptr<CVar> ConsoleVariable::MakeString(const char* value) {
+    auto result = std::make_shared<CVar>();
+    const size_t bytes = std::strlen(value) + 1;
+    auto storage = static_cast<char*>(std::malloc(bytes));
+    if (!storage) throw std::bad_alloc();
+    std::memcpy(storage, value, bytes);
+    result->String = storage;
+    result->Type = ConsoleVariableType::String;
