+std::shared_ptr<std::vector<std::string>> ArchiveManager::ListFiles(const std::string& searchMask) {
+    std::list<std::string> includes = {};
+    if (!searchMask.empty()) {
+        includes.push_back(searchMask);
+    }
+    return ListFiles(includes, {});
