+size_t ArchiveManager::RemoveArchive(const std::string& path) {
+    for (size_t i = 0; i < mArchives.size(); i++) {
+        if (path == mArchives[i]->GetPath()) {
+            mArchives[i]->Unload();
+            mArchives.erase(mArchives.begin() + i);
+            ResetVirtualFileSystem();
+            return 1;
+        }
+    }
+
+    return 0;
+}
