+// These references remain valid through unordered_map rehash. Archive removal
+// or remount must rebuild the directory before subsequent lookups.
+const ArchiveManager::IndexedPath* ArchiveManager::FindPath(uint64_t hash) const {
+    const auto it = std::lower_bound(mIndex.begin(), mIndex.end(), hash,
+        [](const IndexedPath& entry, uint64_t value) { return entry.hash < value; });
+    return it != mIndex.end() && it->hash == hash ? &*it : nullptr;
+}
+
+void ArchiveManager::RebuildIndex() {
+    mIndex.clear();
+    mDirectories.clear();
+    size_t count = 0;
+    for (const auto& archive : mArchives) count += archive->ListFiles()->size();
+    mIndex.reserve(count);
+    for (size_t i = 0; i < mArchives.size(); ++i) {
+        for (const auto& [hash, path] : *mArchives[i]->ListFiles()) {
+            mIndex.push_back({hash, i, &path});
+            const auto slash = path.find_last_of('/');
+            if (slash != std::string::npos) mDirectories.insert(path.substr(0, slash));
+        }
+    }
+    std::sort(mIndex.begin(), mIndex.end(), [](const IndexedPath& a, const IndexedPath& b) {
+        return a.hash != b.hash ? a.hash < b.hash : a.archive > b.archive;
+    });
+    mIndex.erase(std::unique(mIndex.begin(), mIndex.end(), [](const IndexedPath& a, const IndexedPath& b) {
+        return a.hash == b.hash;
+    }), mIndex.end());
+}
