+std::shared_ptr<IResource> ResourceManager::LoadResourceProcess(const ResourceIdentifier& identifier, bool loadExact,
+                                                                std::shared_ptr<ResourceInitData> initData) {
+    if (OtrSignatureCheck(identifier.Path.c_str())) {
+        return LoadResourceProcess({identifier.Path.substr(7), identifier.Owner, identifier.Parent}, loadExact, initData);
+    }
+    if (!loadExact && mAltAssetsEnabled && !identifier.Path.starts_with(IResource::gAltAssetPrefix)) {
+        const ResourceIdentifier alternative{IResource::gAltAssetPrefix + identifier.Path, identifier.Owner, identifier.Parent};
+        if (auto result = LoadResourceProcess(alternative, true, initData)) return result;
+    }
+    const auto cached = CheckCache(identifier, true);
+    if (auto result = GetCachedResource(cached)) return result;
+    if (const auto error = std::get_if<ResourceLoadError>(&cached);
+        error && *error == ResourceLoadError::NotFound) return nullptr;
+
+    std::shared_ptr<IResource> decoded;
+    bool absent = false;
+    try {
+        auto file = LoadFileProcess(identifier);
+        const auto metadata = identifier.Path + ".meta";
+        const bool aliasExists = identifier.Parent ? identifier.Parent->HasFile(metadata) : mArchiveManager->HasFile(metadata);
+        if (file || aliasExists) decoded = GetResourceLoader()->LoadResource(identifier.Path, file, initData);
+        else absent = !(identifier.Parent ? identifier.Parent->HasFile(identifier.Path) : mArchiveManager->HasFile(identifier.Path));
+    } catch (const std::exception& error) {
+        std::fprintf(stderr, "Blinky resource unavailable: %s: %s\n", identifier.Path.c_str(), error.what());
+    }
+    // Archive/decoder failure remains retryable. Only absence from the index
+    // creates a negative entry; an independently completed load always wins.
+    return PublishResourceLoad(identifier, std::move(decoded), absent);
+}
