+std::shared_ptr<IResource> ResourceManager::PublishResourceLoad(const ResourceIdentifier& identifier,
+    std::shared_ptr<IResource> resource, bool definitelyMissing) {
+    std::shared_ptr<IResource> displaced;
+    std::unique_lock guard(mMutex);
+    auto found = mResourceCache.find(identifier);
+    if (found != mResourceCache.end()) {
+        if (auto current = std::get_if<std::shared_ptr<IResource>>(&found->second); current && *current) {
+            if (!(*current)->IsDirty()) return *current;
+            displaced = *current;
+        }
+    }
+    if (resource) mResourceCache.insert_or_assign(identifier, resource);
+    else if (definitelyMissing && found == mResourceCache.end())
+        mResourceCache.emplace(identifier, ResourceLoadError::NotFound);
+    // guard is destroyed before displaced and the resource parameter.
+    return resource;
+}
