#include "libultraship/libultra/message.h"
#include "libultraship/libultra/internal.h"
#include <mutex>

// The native port drives its scheduler explicitly. Queue operations are bounded
// and nonblocking, including OS_MESG_BLOCK, as required by that scheduler.
// One mutex also serializes initialization with game/audio producers.
namespace {
std::mutex queueMutex;
enum class Action { Append, Prepend, Remove };

s32 Transfer(OSMesgQueue* queue, OSMesg* message, Action action) {
    std::lock_guard<std::mutex> guard(queueMutex);
    if (!queue || !queue->msg || queue->msgCount <= 0 || queue->validCount < 0 ||
        queue->validCount > queue->msgCount || queue->first < 0 || queue->first >= queue->msgCount) {
        return -1;
    }
    const bool removing = action == Action::Remove;
    if (removing ? queue->validCount == 0 : queue->validCount == queue->msgCount) return -1;

    s32 slot = queue->first;
    if (action == Action::Append) {
        const s32 available = queue->msgCount - slot;
        slot = queue->validCount < available ? slot + queue->validCount : queue->validCount - available;
    } else if (action == Action::Prepend) {
        slot = slot ? slot - 1 : queue->msgCount - 1;
        queue->first = slot;
    }
    if (removing) {
        if (message) *message = queue->msg[slot];
        queue->first = slot + 1 == queue->msgCount ? 0 : slot + 1;
        --queue->validCount;
    } else {
        queue->msg[slot] = *message;
        ++queue->validCount;
    }
    return 0;
}
}

extern "C" {
__OSEventState __osEventStateTab[OS_NUM_EVENTS] = {};

void osCreateMesgQueue(OSMesgQueue* queue, OSMesg* storage, s32 capacity) {
    if (!queue) return;
    std::lock_guard<std::mutex> guard(queueMutex);
    *queue = {};
    if (capacity > 0 && storage) {
        queue->msg = storage;
        queue->msgCount = capacity;
    }
}

s32 osSendMesg(OSMesgQueue* queue, OSMesg message, s32) {
    return Transfer(queue, &message, Action::Append);
}

s32 osJamMesg(OSMesgQueue* queue, OSMesg message, s32) {
    return Transfer(queue, &message, Action::Prepend);
}

s32 osRecvMesg(OSMesgQueue* queue, OSMesg* message, s32) {
    return Transfer(queue, message, Action::Remove);
}

void osSetEventMesg(OSEvent event, OSMesgQueue* queue, OSMesg message) {
    if (event >= OS_NUM_EVENTS) return;
    std::lock_guard<std::mutex> guard(queueMutex);
    __osEventStateTab[event] = {queue, message};
}
}
